    for i in range(l-1, r):
        a2[i] = max(a[i] - x, 1)

# Functions for query #2 (find LCA)
def find_lca(a, a2, u, v):
    while True:
        u2 = u
        v2 = v

        # Reduce path lengths
        while a2[u2] <= a[u] and u != 1:
            u2 = a2[u2]

        # Reduce path lengths
        while a2[v2] <= a[v] and v != 1:
            v2 = a2[v2]

        # If both continue on the same node, then LCA is that node
        if u2 == v2:
            return max(u, v)

        # Ensure u2 / v2 is finite by reaching a common ancestor
        if a[u2] < a[v2] and a[v2] < a[u]:
            u = a[u2]
        elif a[u2] > a[v2] and a[v2] > a[u]:
            v = a[v2]

