from collections import deque

def detect_cycle(adjacency_list):
    visited = set()
    stack = []
    for node in adjacency_list:
        if node in visited:
            continue
        if detect_cycle_helper(node, adjacency_list, visited, stack):
            return True
    return False

def detect_cycle_helper(node, adjacency_list, visited, stack):
    visited.add(node)
    stack.append(node)
    for neighbor in adjacency_list[node]:
        if neighbor in visited:
            continue
        if detect_cycle_helper(neighbor, adjacency_list, visited, stack):
            return True
    stack.pop()
    return False

def reconstruct_tree(adjacency_list):
    components, visited = set(), []
    for node in adjacency_list:
        stack = []
        if detect_cycle_helper(node, adjacency_list, set(), stack) and node not in visited:
            components.add(node)
            traverse = [node]
            stack.append(node)
            while stack:
                n = stack.pop()
                visited.append(n)
                for neighbor in adjacency_list[n]:
                    if neighbor not in visited:
                        traverse.append(neighbor)
                        stack.append(neighbor)
            if len(traverse) > 2:
                n0, n1 = traverse[0], traverse[-1]
                for i in range(1, len(traverse)):
                    adjacency_list[n0].add(traverse[i])
                    adjacency_list[n1].add(traverse[i-1])
                return traverse[0], traverse[-1], adjacency_list
    return None

def load_data(fp):
    adjacency_list = {}
    n = int(fp.readline().split()[0])
    for _ in range(n):
        m = int(fp.readline().split()[0])
        edges = []
        for _ in range(m):
            edges.append([int(x) for x in fp.readline().split()])
        adjacency_list[n] = edges
    return adjacency_list

def restore_tree(adjacency_list):
    answers = []
    for (n, node, adjacency) in adjacency_list.values():
        path = reconstruct_tree(adjacency)
        if path is not None:
            if n - 1 == len(path[1:]):
                answers.append(f'YES\n{" ".join([str(x) for x in path])}')
    return '\n'.join(answers)

def main():
    n_cases = int(input().split()[0])
    for i in range(n_cases):
        adjacency_list = load_data(input().split())
        restore_tree(adjacency_list)

if __name__ == '__main__':
    main()
