import sys

# Function to calculate the capacity of the breadboard given its dimensions and initial port coloring
def calculate_capacity(n, m, initial_red_ports, initial_blue_ports):
    red_ports = [False] * n
    blue_ports = [False] * m

    for i in range(m):
        red_ports[i] = initial_red_ports[0][i] == 'R'
        blue_ports[0][i] = initial_blue_ports[0][i] == 'R'

    for i in range(1, m):
        blue_ports[0][i] = blue_ports[0][i-1] or (initial_blue_ports[0][i] == 'R')

    for j in range(n):
        red_ports[j] = initial_red_ports[j][0] == 'R'
        blue_ports[m-1][j] = initial_blue_ports[m-1][j] == 'R'

    for j in range(n-1, 0, -1):
        red_ports[j-1] = red_ports[j] or (initial_red_ports[j-1][0] == 'R')

    row_capacity = 0
    col_capacity = 0

    for i in range(m):
        if red_ports[i] and blue_ports[i] and sum(1 for _ in range(m-1) if blue_ports[i:]) > 0:
            row_capacity += 2

    for i in range(n):
        if red_ports[i] and blue_ports[i] and sum(1 for _ in range(n-1) if blue_ports[:][:n][i] > 0):
            col_capacity += 2

    return max(row_capacity, col_capacity)

# Example usage
