from string import ascii_lowercase

def find_max_value(k, t_c, s):
    char_map = defaultdict(lambda: set(ascii_lowercase))
    occurrence = defaultdict(int)

    for t, c in t_c:
        for t_i in t:
            char_map[t_i] |= set(t)
        # Calculate total possible occurrences of the string in the search string
        tot_occ = max(occurrence[t_i - 'a'] + 1, 0) for t_i in t

    max_val = 0
    for i, char in enumerate(s):
        if char != '?':
            new_val = 0
            for char2 in char_map[char]:
                for t, c in t_c:
                    occ = tot_occ
                    for t_i in t:
                        if t_i != char2 and t_i != char:
                            occ -= sum(occurrence[t_i - 'a'] for t_i in t if t_i != char)
                    if len(t) < k and s[i:i+len(t)] == t:
                        occ -= len(t)
                    new_val = max(new_val, len(t) * c + occ * char_map[t_i][char2] for t_i in t)
            max_val = max(max_val, new_val)

    return max_val

