from collections import defaultdict
from itertools import combinations

def build_tree(drawings):
    for drawing in drawings:
        graph = defaultdict(list)
        edges = drawing.split()[1:]
        for i, j in edges:
            i, j = map(int, (i, j))
            graph[i].append(j)
            graph[j].append(i)
        yield from graph_nontrivial([(i+1, val+1) for (i, val) in graph.items()])

def graph_nontrivial(graph):
    for component in decompose(graph):
        yield component

def decompose(graph):
    seen = set()
    for node in graph.keys():
        if node not in seen:
            children = graph_nontrivial(node)
            if any([len(child) > 1 for child in children]):
                seen.update(complement(children))
                yield from decompose(dict(zip(complement(children), children)))
            elif len(children) == 1:
                parent = graph[next(iter(children))]
                seen.add(parent)
                seen.add(node)
                seen.add(next(iter(children)))
                yield parent, node
        else:
            seen.add(node)

    yield seen

def complement(participants):
    return {card for card in range(1, len(participants)) if card not in participants}

T = int(input())
for _ in range(T):
