    # To resolve duplicates consider all the possible variables. 
    possible_rules = defaultdict(set)

    for i in range(m - 1, -1, -1):
        prefixes = defaultdict(set)
        for word_mask in possible_rules[m * i]:
            for word in words:
                words_mask = word_mask
                for j, ch in enumerate(word):
                    if i + j < m:
                        ch = word[i + j]
                    words_mask |= masks[ord(ch) - 97]
                rules = [f"{c}" for c in word_mask]
                prefixes[words_mask].add("".join(sorted(rules)))
        # Create copies of rules which can resolve ambiguity.
        possible_of = set()
        for words_mask, possible in prefixes.items():
            if len(possible) > 1:
                for possible_rule in sorted(possible):
                    possible_of.add(f"s{i}{possible_rule}")
        possible_rules[i] = set(possible_of)

    # Number of different chains.
    chain_count = 0
    for seq in possible_rules[0]:
        if len(seq) == len(set(seq)):
            chain_count += 1
