def find_k_tile_strings(pattern):
    @lru_cache(maxsize=None)
    def dp(index):
        if index == 0:
            return (-1, 0, (1 << 'abcdefghijklmnopqrstuvwxyz'.index(pattern[0])))

        min_cost = float('inf')
        best_string = []
        for k, new_char in enumerate('abcdefghijklmnopqrstuvwxyz'):
            if k == pattern[index-1]:
                continue
            next_cost = count_substrings(pattern[index-1])[(char := new_char)] - count_substrings(pattern[index-1])[(pattern[index-1])] + 1
            right, cost, used_mask = dp(index-1)
            if not right:
                continue
            if new_char not in best_string or (char in best_string and used_mask & (1 << best_string.index(char))):
                best_cost = cost + min_cost + next_cost
                best_string = [char] + list(best_string)
            else:
                best_cost = max(best_cost, cost + next_cost)
                best_string = [char] + list(best_string)
            max_substring_mask = used_mask + (1 << char)
            if not k:
                min_cost = min(min_cost, cost)
            if min_cost > cost:
                best_cost = float('inf')
            if used_mask == max_substring_mask:
                max_substring_mask -= (1 << best_string[-1])
        return (best_cost, best_string, right)
    _, best_string, right = dp(len(pattern) - 1)
    return pattern[:len(pattern) - len(best_string)], best_string[1:], sum((1 << (index - 1) ^ bitmask) for index, bitmask in enumerate(right))

