from math import comb

def calculate_beauty(n, k, a):
    MOD = 998244353
    lessers = {}
    beauty_sum = 0

    # Count the number of elements less than or equal to each element in the array
    for value in a:
        if value not in lessers:
            lessers[value] = 0
        if value == 0:
            lessers[0] += 1
        lessers[min(10**5 + 1, value)] += 1

    # Calculate the sum of the entire array
    for i in range(1, 10**5 + 1):
        if i in lessers:
            if lessers[i] > 0:
                beauty_sum += lessers[i] * comb(lessers[i] + 1, 2) // comb(lessers[i] + 1, lessers[i] + 1)
                beauty_sum %= MOD

    # Calculate the sum of subsequences of length k
    for sub in combinations_with_replacement(a, k):
        product = 1
        for num in sub:
            if num < 10**5:
                product *= lessers.get(min(10**5 + 1, num), 0)
                product %= MOD
        beauty_sum += product
        beauty_sum %= MOD

    return beauty_sum

