# Function to handle two types of queries
def handle_queries(n, q, queries):
    parent = [-1] + list(range(1, n + 1))  # Array to store parents

    # Function to find LCA using the path compression method
    def find(u):
        if u != parent[u]:
            parent[u] = find(parent[u])
        return parent[u]

    # Function to merge two nodes by using path compression
    def merge(u, v):
        u = find(u)
        v = find(v)
        if u != v:
            parent[u] = v

    # First type of query handler
    def query_type_1(query):
        l, r, x = query
        for i in range(l, r + 1):
            if parent[i] == 1:
                parent[i] = parent[i - 1] - x
                if parent[i] > 0:
                    parent[i] += parent[i - 1]

    # Second type of query handler
    def query_type_2(query):
        u, v = query
        u = find(u)
        v = find(v)
        if u != v:
            merge(u, v)

    # Process each query
    for query in queries:
        if query[0] == 1:
            query_type_1(query)
        elif query[0] == 2:
            merge(find(query[1]), find(query[2]))

