    for i in range(N-1):
        u, v = map(int, input().split())
        u -= 1
        v -= 1
        graph[u].append(v)
        graph[v].append(u)
    for a0 in map(int, input().split()):
        a0 -= 1
        zero_node_counts[a0] += 1

    alpha = dfs(0, -1, graph, {0: {}})
    c = 0
    for entry in alpha.values():
        if entry > 0:
            c += 1
    c = (c % MOD) * pow(c, MOD-2, MOD) % MOD
    for num in zero_node_counts:
        c = (1 + c) * pow(num % MOD, MOD-2, MOD) % MOD
    c = pow(c, MOD-2, MOD) * pow(5, MOD-2, MOD) % MOD
    if T != 1:
