def calculate_edge_values(n, vertex_colors, edges):
    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u-1].append(v-1)
        graph[v-1].append(u-1)

    value = [0] * n

    for start_vertex in range(n):
        new_tasks = [start_vertex]
        values = [0] * n

        while new_tasks:
            vertex = new_tasks.pop(0)
            values[vertex] = sum(vertex_colors[root % n] for root in new_tasks)

            for neighbor in graph[vertex]:
                value[vertex] += values[neighbor]
                del values[neighbor]
                new_tasks.append(neighbor)

        value_vertex_colors = [None] * n
        for i, color in enumerate(vertex_colors):
            if color not in value_vertex_colors:
                value_vertex_colors[color % n] = i

        for i in range(n):
            vertex_colors[i] = value_vertex_colors[vertex_colors[i]]

        for i, edge in enumerate(edges):
            edges[i] = (vertex_colors[edge[0] % n], vertex_colors[edge[1] % n])

    return " ".join(str(value[i]) for i in range(n-1))

