from typing import List, Set
from collections import defaultdict

def reconstruct_tree(drawings: List[int], k: int) -> List[List[int]]:
    graph = defaultdict(set)

    for i in range(k):
        edges = drawing[:i+1]
        for edge in edges:
            graph[edge[1]].add(edge[0])
            graph[edge[0]].add(edge[1])
            drawing.remove(edge)
        drawing.remove(edges)

    def explore(start: Set[int]) -> None or List[List[int]]:
        visited, path = set(), [next(iter(start))]
        stack = [start]

        while stack:
            node = stack.pop()
            visited.add(node)

            for neighbor in graph[node] - visited:
                path.append(neighbor)
                stack.append(neighbor)

        return [(path[i], path[i+1]) for i in range(len(path)-1)]

    for start in graph:
        if len(start) == 1:
            tree = explore(set([start]))
            if len(tree) == (k - 1):
                return tree

    return [], -1

